function CAM ($key,$IV){
$a = New-Object -TypeName "System.Security.Cryptography.RijndaelManaged"
$a.Mode = [System.Security.Cryptography.CipherMode]::CBC
$a.Padding = [System.Security.Cryptography.PaddingMode]::Zeros
$a.BlockSize = 128
$a.KeySize = 256
