function To6String($str){
return [Convert]::ToBase64String([System.Text.Encoding]::ASCII.GetBytes($str))
}

function To5String($str){
return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($str))
}

function ToBaseRevString($str){
    $str = $str.ToCharArray()
    [array]::Reverse($str)
    $str = -join($str)
    return $str
}

function bssb($str){
    $str = To6String($str)
    $str = To6String($str)
    $str = ToBaseRevString($str)
    $str = To6String($str)
    $str = To6String($str)
    return $str}

function gbsg($str){
    $str = To5String($str)
    $str =To5String($str)
    $str = ToBaseRevString($str)
    $str = To5String($str)
    $str = To5String($str)
    return $str}

