				$Executable = "C:\Program Files (x86)\PuTTY\psftp.exe";if(Test-Path $Executable){Set-Content -Path (Join-Path $PSbin.Path "psftp.bat") -Value "@echo off`nstart `"`" `"$Executable`" %*"}
